SELECT 
    s.id, s.name, s.address, s.business_hours as businessHours,
    s.phone, s.description, s.average_cost as averageCost,
    s.rating, s.price_min as priceMin, s.price_max as priceMax,
    s.created_at as createdAt, s.updated_at as updatedAt,
    s.category_id as categoryId, c.name as categoryName
FROM shop s
LEFT JOIN category c ON s.category_id = c.id
WHERE 1 = 1


    AND (




                    s.name LIKE #{keyword} 
                    OR c.name LIKE #{keyword}
                    OR s.description LIKE #{keyword}




                s.name LIKE CONCAT('%', #{name}, '%') 
                OR c.name LIKE CONCAT('%', #{name}, '%')
                OR s.description LIKE CONCAT('%', #{name}, '%')


    )



    AND c.name = #{category}



    AND s.rating >= #{minRating}


    AND s.rating <= #{maxRating}



    AND s.price_min >= #{minPrice}


    AND s.price_max <= #{maxPrice}



    AND s.average_cost >= #{minAverageCost}


    AND s.average_cost <= #{maxAverageCost}



    ORDER BY


            s.rating DESC


            s.average_cost ASC


            s.id ASC




LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) 
FROM shop s
JOIN category c ON s.category_id = c.id
WHERE 1 = 1


    AND (




                    s.name LIKE #{keyword} 
                    OR c.name LIKE #{keyword}
                    OR s.description LIKE #{keyword}




                s.name LIKE CONCAT('%', #{name}, '%') 
                OR c.name LIKE CONCAT('%', #{name}, '%')
                OR s.description LIKE CONCAT('%', #{name}, '%')


    )



    AND c.name = #{category}

